public sealed class GenerationMiningExplosives1458Tests
{
    public static IEnumerable<object[]> OriginalCases()
    {
        using var stream=new GZipStream(new MemoryStream(Convert.FromBase64String(OriginalData)),CompressionMode.Decompress);using var text=new StreamReader(stream);
        while(text.ReadLine() is {} line){var parts=line.Split('\t');yield return new object[]{int.Parse(parts[0]),int.Parse(parts[1]),int.Parse(parts[2]),parts[3]=="1",parts[4],parts[5],Parse(parts[6]),Parse(parts[7])};}
        static int[] Parse(string value)=>value.Length==0?[]:value.Split(',').Select(int.Parse).ToArray();
    }
    [Theory]
    [MemberData(nameof(OriginalCases))]
    public void Actual_original_mining_explosives_matches_whole_tiles_rng_and_both_ordered_structure_lists(int seed,int profile,int tiers,bool returned,string grid,string rng,int[] structures,int[] protectedStructures)
    {
        var w=new Workspace(180,220);w.InitializeVanillaStructureMap();w.InitializeVanillaGenerationSolidity();Assert.True(w.TileStore.TryAttachTileEntities([],1000));foreach(int type in new[]{481,482,483})w.SetVanillaGenerationSolid(new(type),false);
        w.SetVanillaBootstrapState(new(){HellChestItems=[],TreeX=[],TreeStyle=[],CaveBackX=[],CaveBackStyle=[],ForestBackgroundStyles=[],CopperBar=(tiers&1)==0?20:703,IronBar=(tiers&2)==0?22:704,SilverBar=(tiers&4)==0?21:705,GoldBar=(tiers&8)==0?19:706});
        for(int x=0;x<180;x++)for(int y=0;y<220;y++)
        {
            int key=(x*13+y*7)%31;bool active=!(x>=85&&x<=95&&y>=60&&y<=90);ushort type=1;
            if(profile>=13){int half=2+(profile-13)%8,depth=profile<21?150:profile<29?200:100;active=!(x>=90-half&&x<=90+half&&y>=60&&y<=depth);}
            if(profile>=34){int half=2+(profile-34)%8,depth=profile<42?90:150;active=!(x>=90-half&&x<=90+half&&y>=60&&y<=depth);if(!active&&(key+profile)%3!=0){type=(ushort)(profile%2==0?135:3);active=true;}}
            if(profile==1&&x==90&&y==90)active=true;if(profile==4)active=false;if(profile==5&&key%3!=0)active=false;if(profile==7&&x is 82 or 98&&y==90)type=21;
            var tile=new WorldTile{Type=type,Flags=active?WorldTileFlags.Active:0,Wall=(ushort)(profile is 2 or 3&&x==90&&y==90?(profile==2?216:187):profile>=34?350:profile==10?0:15),FrameX=18,FrameY=36,TileColor=7,WallColor=9};
            if(profile is 8 or 9&&!active){tile.LiquidAmount=255;tile.LiquidKind=profile==8?WorldLiquidKind.Lava:WorldLiquidKind.Honey;}
            if(profile is 11 or 12){tile.Flags|=WorldTileFlags.WireRed|WorldTileFlags.WireBlue|WorldTileFlags.Actuator|WorldTileFlagMasks.Visibility|WorldTileFlagMasks.Fullbright;tile.TrySetSourceShape(key%3==0,(byte)(key%5));if(profile==12)tile.Flags|=WorldTileFlags.Inactive;}
            w.TileStore.Set(x,y,tile);
        }
        if(profile==6)w.VanillaStructureMap.AddProtectedStructure(new(60,60,60,60));
        var random=new MiningRandom(seed);Assert.Equal(returned,MicroMiningExplosives1458.Place(w,random,90,90));
        using var bytes=new MemoryStream();using(var writer=new BinaryWriter(bytes))
            for(int x=0;x<180;x++)for(int y=0;y<220;y++){var t=w.TileStore.Get(x,y);writer.Write(t.Type);writer.Write(t.Wall);writer.Write(t.FrameX);writer.Write(t.FrameY);writer.Write(t.LiquidAmount);writer.Write((byte)t.LiquidKind);writer.Write(t.Shape);writer.Write(t.TileColor);writer.Write(t.WallColor);writer.Write((ushort)t.Flags);}
        Assert.Equal(grid,Convert.ToHexString(SHA256.HashData(bytes.ToArray())));
        using var state=new MemoryStream();using(var writer=new BinaryWriter(state)){writer.Write((uint)typeof(VanillaUnifiedRandom1458).GetField("inext",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!);foreach(int value in (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!)writer.Write(value);}
        Assert.Equal(rng,Convert.ToHexString(SHA256.HashData(state.ToArray())));
        static int[] Flatten(WorldTileRegion[] values)=>values.SelectMany(r=>new[]{r.X,r.Y,r.Width,r.Height}).ToArray();
        Assert.Equal(structures,Flatten(w.VanillaStructureMap.CaptureStructures()));Assert.Equal(protectedStructures,Flatten(w.VanillaStructureMap.CaptureProtectedStructures()));
    }
    private sealed class MiningRandom(int seed):IWorldGenerationVanillaRandom
    {
        internal readonly VanillaUnifiedRandom1458 Source=new(seed);
        public int Next()=>Source.Next();public int Next(int max)=>Source.Next(max);public int Next(int min,int max)=>Source.Next(min,max);public double NextDouble()=>Source.NextDouble();public void NextBytes(byte[] bytes)=>Source.NextBytes(bytes);
    }
